stops={'TAA','TAG','TGA'}

def stopfree(s):
    out=[]
    for frame in range(3):
        pos=frame
        start=frame
        while pos+3<=len(s):
            if s[pos:pos+3] in stops:
                if pos-start>=90:
                    out.append((start,pos,(pos-start)//3,frame))
                start=pos+3
            pos+=3
        if len(s)-start>=90:
            out.append((start,len(s),(len(s)-start)//3,frame))
    return out

